// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public {
        c = new demo();
    }

    function testFuzz_property(uint256 amount, address recipient) public {
        address[] memory tos = new address[](1);
        tos[0] = recipient;

        RecordingCallee rec = new RecordingCallee();

        bool ok;
        try c.transfer(address(this), address(rec), tos, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        bool amountsMatch = true;
        for (uint256 i = 0; i < rec.count(); i++) {
            if (rec.amounts(i) != amount) {
                amountsMatch = false;
                break;
            }
        }

        assertTrue(ok == false || amountsMatch);
    }
}

contract RecordingCallee {
    uint256 private _count;
    uint256[] private _amounts;

    function transferFrom(address, address, uint256 value) external returns (bool) {
        _count++;
        _amounts.push(value);
        return true;
    }

    function count() external view returns (uint256) {
        return _count;
    }

    function amounts(uint256 i) external view returns (uint256) {
        return _amounts[i];
    }
}
